<?php require '../includes/config.php'; require '../includes/layout.php';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_verify();$name=trim($_POST['full_name']);$email=strtolower(trim($_POST['email']));$matric=trim($_POST['matric_number']);$dept=(int)$_POST['department_id'];$pass=$_POST['password'];$confirm=$_POST['confirm_password'];if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||!$matric||!$dept||strlen($pass)<8)$error='Please complete all fields; password must be at least 8 characters.';elseif($pass!==$confirm)$error='Passwords do not match.';else{$hash=password_hash($pass,PASSWORD_DEFAULT);try{$stmt=$conn->prepare("INSERT INTO users(full_name,email,matric_number,department_id,password_hash,role) VALUES(?,?,?,?,?,'student')");$stmt->bind_param('sssis',$name,$email,$matric,$dept,$hash);$stmt->execute();flash('success','Account created successfully. You can now sign in.');redirect('login.php');}catch(mysqli_sql_exception $e){$error='Email or matric number is already registered.';}}}
$departments=$conn->query('SELECT id,name FROM departments ORDER BY name')->fetch_all(MYSQLI_ASSOC);public_head('Student Registration');?><section class="auth-page"><div class="auth-box card-panel"><h2>Create Student Account</h2><?php if(!empty($error))echo'<div class="alert alert-error">'.e($error).'</div>'; ?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label class="label">Full Name</label><input name="full_name" required value="<?=e($_POST['full_name']??'')?>"><label class="label">Email Address</label><input type="email" name="email" required value="<?=e($_POST['email']??'')?>"><label class="label">Matric Number</label><input name="matric_number" required><label class="label">Department</label><select name="department_id" required><option value="">Select department</option><?php foreach($departments as $d)echo'<option value="'.(int)$d['id'].'">'.e($d['name']).'</option>';?></select><label class="label">Password</label><input type="password" name="password" minlength="8" required><label class="label">Confirm Password</label><input type="password" name="confirm_password" minlength="8" required><button class="btn btn-primary" style="width:100%">Create Account</button></form><p>Already registered? <a href="login.php">Sign in</a></p></div></section><?php public_footer(); ?>